class EmbedScalarField(Node):
    def __init__(self, parent_node_id : str, colormap : str = "cool warm"):

        if correctness_checks_on():
            if colormap not in options_lists["colormaps"]:
                raise Exception(f"Colormap for EmbedScalarField must match one of the valid options ({enumerate_list(colormaps)})")

        super().__init__(parent_node_id, Scalar, SurfaceOrVolumeEmbedding, locals(), True, True)
        self.colormap = colormap

    @classmethod
    def chat_description(cls):
        return "queued embedding scalar field"

    @classmethod
    def description(cls):
        from topopilot.config import correctness_checks_on
        desc = 'Creates a geometric embedding of a node of type scalar. '

        if correctness_checks_on():
            desc += 'Make sure to use this on the un-simplified scalar field '\
                    'unless the user says otherwise (if they say nothing, assume they want the un-simplified one)'

        return desc

    @classmethod
    def param_descriptions(cls):
        return {'parent_node_id': 'The node corresponding to the scalar field that is being visualized.',
         'colormap': 'The colormap used for the visualization. Select one from '
                     'OPTIONS:colormaps.'}

    def compatible_to_visualize(self, other):
        if issubclass(other.node_type, SquareOrCubeEmbedding):
            return False, f"Cannot embed a node of type {self.node_type.get_mcp_name()} along with another "\
                          f"of type {other.node_type.get_mcp_name()}. They will overlap in the visualization"

        return True, ""

    def _evaluation_logic(self, parent_data, time_step):
        sf = servermanager.Fetch(parent_data[0].data)
        dimensions = self.root_node.dimensions

        opacity_tf = None

        if not is_2d(dimensions):

            opacity_tf = []

            numPoints = sf.GetNumberOfPoints()
            skip = int(numPoints/1000000)
            if skip == 0:
                skip = 1
            array = sf.GetPointData().GetArray("Scalars_")

            values = []

            for i in range(0, numPoints, skip):
                values.append(array.GetTuple1(i))
            numPoints = len(values)
            values.sort()

            window_size = int(0.2*numPoints)

            greatest_window = None
            greatest_window_range = -float('inf')

            for i in range(1,numPoints-window_size):
                window_range = values[i+window_size] - values[i]
                if window_range > greatest_window_range:
                    greatest_window = i
                    greatest_window_range = window_range

            # rename for ease of writing
            w = values[greatest_window]
            r = greatest_window_range

            opacity_tf.append((w, 0.0))
            opacity_tf.append((w + 0.25*r, 0.2))
            opacity_tf.append((w + 0.375*r, 0.5))
            opacity_tf.append((w + 0.5*r, 1.0))
            opacity_tf.append((w + 0.625*r, 0.5))
            opacity_tf.append((w + 0.75*r, 0.2))
            opacity_tf.append((w + r, 0.0))

        return SurfaceOrVolumeEmbedding(parent_data[time_step-1].data, self.colormap, opacity_tf, dimensions, False, True)

    def _evaluation_logic_partial_cache(self, parent_data, partial_cache, time_step):
        partial_cache.data = parent_data.data
        return partial_cache

    @classmethod
    def guardrails(cls):
        def guardrail_function(parent_node_id, colormap):
            if tree.has_node(parent_node_id) and type(tree.node(parent_node_id)).__name__ == "PersistenceSimplification":
                raise Exception("Error: You are creating a visualization of a simplified scalar field, however the user did not "
