                                "should assume that the unsimplified scalar field should be visualized.")

        return [
            Guardrail(
                "Unless the user explicitly says otherwise, this should be used to visualize the un-simplified scalar field.",
                "user_allowed_visualizing_simplified_scalar_field",
                "Set to True if the explicitly clarified that they want the simplified scalar field to be visualized.",
                guardrail_function
            ),
            _visualize_alongside_descriptors_guardrail
        ]

